/*
 * This function is designed to process input data.
 * The 'input' parameter is expected to contain the entire
 * dataset as a single string, typically from standard input.
 */
function  Main (  input  )
{
  // First, the raw input string is split into an array of lines.
  // Each element in the 'input' array will then represent a line from the original input.
  input  =  input . split (  "\n"  ) ;

  // The second line of input (at index 1, since arrays are 0-indexed)
  // is expected to contain space-separated values.
  // This line is split into individual string elements and stored in 'tmp'.
  tmp  =  input [ 1 ] . split (  " "  ) ;


  // Initialize a counter variable. This will likely track a specific condition.
  var  count  =  0 ;

  // Initialize 'PjMin' with the maximum safe integer value.
  // This is a common pattern for finding the minimum value in a sequence.
  var  PjMin  =  Number . MAX_SAFE_INTEGER ;

  // Begin a loop. The number of iterations is determined by the value
  // on the first line of the input (input[0]).
  for  (  var  i  =  0 ;  i  <  input [ 0 ] ;  i ++  )
  {
    // Retrieve the current element from the 'tmp' array.
    // This element is assigned to 'Pi' for the current iteration.
    var  Pi  =  tmp [ i ] ;

    // Check if the current element 'Pi' is less than or equal to the
    // minimum value found so far ('PjMin').
    if  (  Pi  <=  PjMin  )
    {
      // If the condition is true, increment the 'count' variable.
      count ++ ;
    }

    // This block updates 'PjMin' if 'Pi' is found to be a new minimum.
    // The condition 'PjMin >= Pi' is functionally equivalent to 'Pi <= PjMin'.
    if  (  PjMin  >=  Pi  )
    {
      PjMin  =  Pi ;
    }
  }

  // Finally, print the accumulated 'count' to the console.
  // This is the desired output of the program.
  console . log (  count  ) ;
}

